    "imageUrl": "https://imagens.ebc.com.br/XjjOuHv_IvcpWPr-ATkvBkPamd8=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2026/07/16/0d7a8404.jpg.jpeg?itok=jE_wNCcB",
